import {existsSync,readFileSync} from 'node:fs';import {fileURLToPath} from 'node:url';import {registerHooks,stripTypeScriptTypes} from 'node:module';
registerHooks({resolve(s,c,n){if(s.startsWith('.')&&s.endsWith('.js')&&c.parentURL){const u=new URL(s.slice(0,-3)+'.ts',c.parentURL);if(existsSync(fileURLToPath(u)))return n(u.href,c);}return n(s,c);}});
const {hashJson}=await import('../../packages/contracts/src/canonical.ts'),{IvyError}=await import('../../packages/contracts/src/errors.ts'),{serviceTools}=await import('../../packages/sdk/src/client.ts');
const source=readFileSync('services/task-board/src/runtime/native-comments.ts','utf8').replace(/^import .*;\r?\n/gm,'').replace('export ','');
const sync=new Function('hashJson','serviceTools',stripTypeScriptTypes(source)+'\nreturn syncNativeComments;')(hashJson,serviceTools);
const runId='run',taskId='task',time='2026-01-02T03:04:05.006Z',taskPin={objectId:taskId,revision:3};
const run={primaryResourceRef:{nativeId:'thread'},turnId:'turn',taskId,target:{serviceNodeId:'native-agent'},nativeEpoch:'epoch'};
const task={claim:{run:{objectId:runId}},comments:[]};
const input=(extra={})=>({identity:{serviceNodeId:'native-agent',epoch:'epoch',requestId:1},method:'item/tool/requestUserInput',params:{questions:[{question:'Choose a value.'}]},observedAt:time,updatedAt:time,threadId:'thread',turnId:'turn',state:'pending',answerOperationId:null,answerCallerPrincipalId:null,reply:null,code:null,...extra});
const answered=(reply={result:{answers:{question:{answers:['First','Second']}}}},extra={})=>input({state:'answered',answerOperationId:'answer',answerCallerPrincipalId:'user',reply,...extra});
const questionId='native-question-'+hashJson(input().identity).slice(7),responseId='native-response-'+hashJson(input().identity).slice(7);
const rows=[],add=(name,extra={})=>rows.push({name,input:{run,task,items:[input()],...extra}});
add('pending question');add('empty page',{items:[]});add('no primary',{run:{...run,primaryResourceRef:null}});add('no turn',{run:{...run,turnId:null}});
add('claim moved',{task:{...task,claim:{run:{objectId:'other'}}}});add('claim absent',{task:{...task,claim:null}});
for(const [key,value]of[['threadId','other'],['turnId','other']])add('different '+key,{items:[input({[key]:value})]});
add('different owner',{items:[input({identity:{...input().identity,serviceNodeId:'other'}})]});add('different epoch',{items:[input({identity:{...input().identity,epoch:'other'}})]});add('null turn accepted',{items:[input({turnId:null})]});
add('answering request',{items:[input({state:'answering',reply:{result:{}},answerOperationId:'answer',answerCallerPrincipalId:'user'})]});add('uncertain request',{items:[input({state:'outcome_unknown'})]});
add('answered choices',{items:[answered()]});add('expired request',{items:[input({state:'expired'})]});
add('decision answer',{items:[answered({result:{decision:'approve'}})]});add('error reply fallback',{items:[answered({error:{code:-1,message:'error'}})]});
add('object and null answer values',{items:[answered({result:{answers:{q:{answers:[null,17,true,{value:'x'},['nested','array']]}}}})]});
add('answers numeric key order',{items:[answered({result:{answers:{2:{answers:['two']},1:{answers:['one']},a:{answers:['last']}}}})]});
add('string answer flatMap',{items:[answered({result:{answers:[{answers:'text'}]}})]});
add('empty answer',{items:[answered({result:{answers:{q:{answers:[]}}}})]});add('empty decision',{items:[answered({result:{decision:''}})]});
add('secret answer',{items:[answered(undefined,{params:{questions:[{question:'Secret value?',isSecret:true}]}})]});
add('pending secret',{items:[input({params:{questions:[{question:'Secret value?',isSecret:true}]}})]});
add('nested secret',{items:[answered(undefined,{params:{questions:[{question:'Secret value?'}],nested:{isSecret:true}}})]});
add('false secret',{items:[answered(undefined,{params:{questions:[{question:'Visible?',isSecret:false}]}})]});
add('secret-looking literal is not marker',{items:[answered(undefined,{params:{reason:'Text "isSecret":true'}})]});
add('reason prompt',{items:[input({params:{reason:'Permission needed.'}})]});add('fallback prompt',{items:[input({params:null})]});add('empty reason',{items:[input({params:{reason:''}})]});
add('question coercion',{items:[input({params:{questions:[{question:'First'},{question:17},{question:true},{question:0},{question:[]}]}})]});
add('UTF16 answer bound',{items:[answered({result:{answers:{q:{answers:['A'+'😀'.repeat(8000)]}}}})]});
add('duplicate pending input',{items:[input(),input()]});add('pending then answered',{items:[input(),answered()]});
add('distinct string request ID',{items:[input(),input({identity:{...input().identity,requestId:'1'}})]});
add('question already saved',{task:{...task,comments:[{commentId:questionId}]}});add('response already saved',{task:{...task,comments:[{commentId:questionId},{commentId:responseId}]},items:[answered()]});
add('answered creates missing question only',{task:{...task,comments:[{commentId:responseId}]},items:[answered()]});
add('null answer object is internal failure',{items:[answered({result:{answers:{q:null}}})]});add('null question is internal failure',{items:[input({params:{questions:[null]}})]});
add('unconvertible answer is internal failure',{items:[answered({result:{answers:{q:{answers:[{toString:'not callable'}]}}}})]});
add('question publication fails',{failAt:1});add('response publication fails',{items:[answered()],failAt:2});add('uncertain publication after write',{items:[answered()],failAt:1,failAfterWrite:true});
add('second pass idempotent',{items:[answered()],passes:2});add('input query fails',{rpcFailure:true});
for(const row of rows){const i=row.input,trace=[],posted=[];let current={pin:structuredClone(taskPin),value:structuredClone(i.task)},writes=0;
 const client={async request(method,params){trace.push(['rpc',method,structuredClone(params)]);if(method==='tools.list')return{provider:{node:{serviceNodeId:'native-agent'}},items:[{qualifiedName:'agent.inputs',definition:{namespace:'agent',name:'inputs',interfaceVersion:'1.0.0',annotations:{readOnlyHint:true},inputSchema:{},outputSchema:{}},definitionHash:'sha256:'+'a'.repeat(64),catalogHash:'sha256:'+'b'.repeat(64)}],nextCursor:null};if(i.rpcFailure)throw new IvyError('fixture_failed','input query');return{epoch:'epoch',items:i.items,truncated:false};}};
 const store={client,async read(key,address,upgrade=true){trace.push(['read',key,address,upgrade]);return key==='task-board/run'?{pin:{objectId:runId,revision:1},value:i.run}:structuredClone(current);}};
 const engine={store,async nativeComment(request){trace.push(['comment',structuredClone(request)]);writes++;if(i.failAt===writes&&!i.failAfterWrite)throw new IvyError('fixture_failed','publication');current.value.comments.push({commentId:request.commentId});current.pin.revision++;posted.push(request);if(i.failAt===writes)throw new IvyError('outcome_unknown','publication','unknown');}};
 let result=null;try{for(let pass=0;pass<(i.passes??1);pass++)await sync(engine,runId);}catch(e){const error=IvyError.from(e);result={code:error.code,message:error.message,outcome:error.outcome};}
 row.expectedHash=hashJson({result,trace,posted,current});
}
process.stdout.write(JSON.stringify({taskPin,rows}));
